import json
def solve(run,case):
    result={}
    for name,config in case['configs'].items():
        code,out,err=run(['kubectl','--kubeconfig',config,'get','configmap',case['name'],'-o','json'])
        if code==0:result[name]=json.loads(out)['metadata']['uid']
        elif 'x509' in err.lower() or 'certificate' in err.lower() or 'tls' in err.lower():result[name]='TLS'
        elif 'forbidden' in err.lower():result[name]='AUTHORIZATION'
        elif 'provide credentials' in err.lower() or 'unauthorized' in err.lower() or 'logged in' in err.lower():result[name]='AUTHENTICATION'
        else:raise RuntimeError(err)
    return result

